        return ax * by - ay * bx;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        long[] x = new long[7];
        long[] y = new long[7];

        for (int i = 0; i < 7; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            x[i] = Long.parseLong(st.nextToken());
            y[i] = Long.parseLong(st.nextToken());
        }

        long v12x = x[1] - x[0], v12y = y[1] - y[0];
        long v13x = x[2] - x[0], v13y = y[2] - y[0];

        boolean valid = v12x * v13x + v12y * v13y > 0
                && v12x * v12x + v12y * v12y == v13x * v13x + v13y * v13y;

        long dx = x[2] - x[1], dy = y[2] - y[1];

        valid &= cross(dx, dy, x[3] - x[1], y[3] - y[1]) == 0;
        valid &= cross(dx, dy, x[4] - x[1], y[4] - y[1]) == 0;

        valid &= x[1] + x[2] == x[3] + x[4]
