        long shortDx = x[4] - x[3], shortDy = y[4] - y[3];
        valid &= dx * dx + dy * dy > shortDx * shortDx + shortDy * shortDy;

        long v46x = x[5] - x[3], v46y = y[5] - y[3];
        long v57x = x[6] - x[4], v57y = y[6] - y[4];

