        valid &= v57x * dx + v57y * dy == 0;
        valid &= v46x * v46x + v46y * v46y == v57x * v57x + v57y * v57y;

        long sideP1 = cross(dx, dy, x[0] - x[1], y[0] - y[1]);
        long sideP6 = cross(dx, dy, x[5] - x[1], y[5] - y[1]);
